function supplementaryStyles() {
  return `.process-layout{display:grid;grid-template-columns:minmax(310px,.72fr) minmax(580px,1.28fr);height:clamp(520px,calc(100vh - 250px),760px);min-height:0;overflow:hidden}.step-list{min-height:0;overflow-y:auto;scrollbar-gutter:stable;overscroll-behavior:contain}.step-inspector{min-width:0;min-height:0;overflow-y:auto;scrollbar-gutter:stable;overscroll-behavior:contain}.step-expectations{display:grid;gap:5px;margin:0 0 14px}.step-expectations>div{display:flex;justify-content:space-between;gap:12px;padding:7px 9px;border-left:3px solid var(--accent);background:var(--accent-soft);font-size:9px}.step-expectations span{color:var(--muted)}.action-details{display:grid;grid-template-columns:130px minmax(0,1fr);margin:0 0 14px;border:1px solid var(--line);background:var(--surface-2)}.action-kind{padding:10px;border-right:1px solid var(--line)}.action-kind span,.action-kind b{display:block}.action-kind span{color:var(--muted);font-size:8px}.action-kind b{margin-top:2px;font-size:11px}.action-details dl{display:flex;flex-wrap:wrap;gap:8px 18px;margin:0;padding:9px 11px}.action-details dt{color:var(--muted);font-size:8px}.action-details dd{margin:1px 0 0;font:9px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.unlinked-knowledge{padding:16px 20px;border-top:1px solid var(--line)}.unlinked-knowledge>header{display:flex;justify-content:space-between;margin-bottom:10px}.unlinked-knowledge>header span{color:var(--muted);font-size:9px}@media(max-width:860px){.process-layout{grid-template-columns:1fr;height:auto;overflow:visible}.step-list{height:min(38vh,320px);border-right:0;border-bottom:1px solid var(--line)}.step-inspector{height:min(62vh,520px)}}@media(max-width:620px){.action-details{grid-template-columns:1fr}.action-kind{border-right:0;border-bottom:1px solid var(--line)}}`;
}

