function checkpointAndMermaidStyles() {
  return `.mermaid-stage{position:relative;min-height:360px;margin-top:18px;padding:16px;border:1px solid var(--line);background:#fbfcfd;overflow:auto}.mermaid-stage svg{display:block;max-width:none;margin:auto}.mermaid .node[data-mermaid-kind]{cursor:pointer;outline:none}.mermaid .node[data-mermaid-kind]:focus-visible,.mermaid .node[data-mermaid-kind].selected{filter:drop-shadow(0 0 5px rgba(14,104,115,.55))}.mermaid-expand{position:sticky;z-index:2;top:0;left:100%;display:grid;place-items:center;width:30px;height:30px;margin-bottom:-30px;padding:0;border:1px solid var(--line-strong);border-radius:4px;background:#fff;color:var(--accent);cursor:pointer}.mermaid-expand .icon{width:15px}.mermaid-error{margin:0;padding:12px;border-left:3px solid var(--fail);background:var(--fail-soft);color:var(--fail);font-size:10px}.flow-node-inspector{margin-top:14px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.flow-node-inspector>article{margin-top:10px;padding:12px 14px;background:var(--surface-2)}.flow-node-inspector article>header{display:flex;align-items:flex-start;justify-content:space-between;gap:14px}.flow-node-inspector article>header span{color:var(--accent);font-size:9px;font-weight:800}.flow-node-inspector article h2{margin:2px 0 0;font-size:13px}.flow-node-inspector article dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:10px 0}.flow-node-inspector article dl div{padding:7px 9px;border-right:1px solid var(--line);background:#fff}.flow-node-inspector article dt{color:var(--muted);font-size:8px}.flow-node-inspector article dd{margin:2px 0 0;font-size:9px}.flow-node-inspector article p{font-size:10px}.status-waived{background:var(--blocked-soft);color:var(--blocked)}.mermaid-viewer{width:min(1180px,calc(100vw - 32px));height:min(900px,calc(100vh - 32px));padding:0;border:1px solid #40505e;border-radius:7px;background:#111a22;color:#eef3f6;overflow:hidden}.mermaid-viewer::backdrop{background:rgba(8,15,21,.72)}.mermaid-viewer>header{display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:58px;padding:9px 12px 9px 16px;border-bottom:1px solid #35434e;background:#1b2731}.mermaid-viewer>header span,.mermaid-viewer>header b{display:block}.mermaid-viewer>header span{color:#8fa2af;font-size:8px}.mermaid-viewer .viewer-controls button{display:grid;place-items:center;width:34px;height:34px;padding:0;border:1px solid #42515d;border-radius:4px;background:#24323d;color:#d7e1e7;cursor:pointer}.mermaid-viewer-stage{height:calc(100% - 58px);overflow:auto;cursor:grab;touch-action:none;user-select:none}.mermaid-viewer-stage.dragging{cursor:grabbing}.mermaid-viewer-canvas{position:relative;min-width:100%;min-height:100%}.mermaid-viewer-frame{position:absolute;transform-origin:top left;background:#fbfcfd}.mermaid-viewer-frame svg{display:block;width:100%;height:100%;max-width:none}.graph-fallback{margin-top:12px;border-top:1px solid var(--line)}.graph-fallback summary{padding:10px 0;color:var(--accent);cursor:pointer;font-size:10px;font-weight:750}.graph-fallback ol{display:grid;gap:5px;margin:0;padding:0;list-style:none}.graph-fallback li{display:grid;grid-template-columns:64px 84px minmax(0,1fr) auto;gap:8px;padding:7px 9px;background:var(--surface-2);font-size:9px}.graph-fallback li span{overflow-wrap:anywhere}.graph-fallback li em{color:var(--blocked);font-style:normal}.checkpoint-toolbar{display:flex;align-items:center;justify-content:space-between;gap:20px;padding-bottom:12px;border-bottom:1px solid var(--line)}.checkpoint-toolbar span,.checkpoint-toolbar b{display:block}.checkpoint-toolbar span{color:var(--muted);font-size:9px}.checkpoint-toolbar b{font-size:13px}.checkpoint-toolbar .segmented{display:flex;flex-wrap:wrap}.checkpoint-toolbar button{padding:5px 9px;border:1px solid var(--line);background:#fff;color:var(--muted);font-size:9px}.checkpoint-toolbar button.active{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}.checkpoint-ledger{display:grid;gap:8px;margin-top:14px}.checkpoint-row{padding:12px 14px;border:1px solid var(--line);border-left:4px solid var(--line-strong);background:#fff;transition:outline-color .2s,box-shadow .2s}.checkpoint-row.targeted{outline:2px solid var(--accent);box-shadow:0 0 0 4px var(--accent-soft)}.checkpoint-row.status-pass{border-left-color:var(--pass)}.checkpoint-row.status-fail{border-left-color:var(--fail)}.checkpoint-row.status-waived{border-left-color:var(--blocked);background:var(--blocked-soft)}.checkpoint-row header{display:grid;grid-template-columns:52px minmax(0,1fr) auto;gap:10px;align-items:center}.checkpoint-row header code{color:var(--accent);font-weight:800}.checkpoint-row header span{font-size:9px;font-weight:750}.checkpoint-row dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:9px 0 0}.checkpoint-row dl div{padding:6px 8px;border-right:1px solid var(--line);background:var(--surface-2)}.checkpoint-row dt{color:var(--muted);font-size:8px}.checkpoint-row dd{margin:1px 0 0;font-size:9px}.checkpoint-row p{margin:8px 0 0;font-size:10px}.checkpoint-row>small{display:block;margin-top:8px;color:var(--muted);font-size:8px}.waiver-reason{color:#745015}@media(max-width:620px){.flow-node-inspector article dl{grid-template-columns:1fr}.checkpoint-toolbar{align-items:flex-start;flex-direction:column}.checkpoint-row header{grid-template-columns:44px minmax(0,1fr)}.checkpoint-row header span{grid-column:2}.checkpoint-row dl{grid-template-columns:1fr}.graph-fallback li{grid-template-columns:50px minmax(0,1fr)}.graph-fallback li span,.graph-fallback li em{grid-column:2}.mermaid-stage{min-height:280px;padding:8px}.mermaid-viewer{width:calc(100vw - 12px);height:calc(100vh - 12px)}}`;
}

function flowWorkspaceStyles() {
  return `.flow-workspace{display:grid;grid-template-columns:minmax(420px,1.15fr) minmax(360px,.85fr);gap:20px;align-items:start;margin-top:18px}.flow-visual-column{min-width:0;position:sticky;top:58px}.flow-information-column{min-width:0;display:grid;gap:20px}.flow-visual-column .mermaid-stage{min-height:520px;max-height:calc(100vh - 150px);margin-top:0}.flow-information-column .flow-node-inspector{margin:0;padding:0 0 16px;border-top:0}.checkpoint-panel{min-width:0;padding-top:4px;border-top:1px solid var(--line)}.checkpoint-row{cursor:pointer}.checkpoint-row:hover,.checkpoint-row:focus-visible,.checkpoint-row.selected{border-color:var(--accent);outline:2px solid var(--accent-soft)}@media(max-width:920px){.flow-workspace{grid-template-columns:1fr}.flow-visual-column{position:static}.flow-visual-column .mermaid-stage{min-height:420px;max-height:none}}@media(max-width:620px){.flow-visual-column .mermaid-stage{min-height:300px}}`;
}

function timingAndStateStyles() {
  return `.status-executed,.status-observed,.status-investigated,.status-recovered{background:var(--pass-soft);color:var(--pass)}.status-unknown{background:var(--pending-soft);color:var(--pending)}.status-issue{background:var(--fail-soft);color:var(--fail)}.metric-strip b,.timing-breakdown dd{font-variant-numeric:tabular-nums;white-space:nowrap}.timing-breakdown{margin-top:12px;border:1px solid var(--line);background:var(--surface-2)}.timing-breakdown>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border-bottom:1px solid var(--line)}.timing-breakdown>header span,.timing-breakdown>header b{display:block}.timing-breakdown>header span{color:var(--muted);font-size:8px}.timing-breakdown>header b{font-size:11px}.timing-breakdown>header small{color:var(--muted);font:9px ui-monospace,SFMono-Regular,Menlo,monospace}.timing-breakdown dl{display:grid;grid-template-columns:repeat(5,minmax(12ch,1fr));margin:0}.timing-breakdown dl div{min-width:0;padding:8px 10px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.timing-breakdown dt{color:var(--muted);font-size:8px}.timing-breakdown dd{margin:2px 0 0;font-size:10px;font-weight:750}@media(max-width:860px){.timing-breakdown dl{grid-template-columns:repeat(2,minmax(12ch,1fr))}}@media(max-width:620px){.timing-breakdown dl{grid-template-columns:minmax(12ch,1fr)}}`;
}

function renderCurrentContextHtml(caseJson, report) {
  const trace = buildExecutionTrace(report);
  const narrative = trace.narrative;
  const views = projectCaseFlowViews(report);
  const shots = screenshotModel(report, trace);
  const platform = report.execution?.platform || report.execution?.targetBinding?.platform || 'harmony';
  const platformLabel = PLATFORM_LABELS[platform] || platform;
  const display = report.display || {};
  const verdict = display.verdict || display.status || 'NOT_RUN';
  const passed = views.coverage.covered;
  const modelTabs = [['case-flow', '用例流程']];
  const runtimePlanTabs = trace.plans.length ? [['runtime-plans', 'Runtime 计划']] : [];
  const tabs = [['overview', '结果概览'], ['source', '原始用例'], ...modelTabs, ['execution-trace', '执行轨迹'], ...runtimePlanTabs, ['logs', '详细日志']];
  const sourcePanel = `<section class="report-panel document-panel" data-panel-view="source" hidden><article class="case-document">${renderSourceMarkdown(report.sourceText || '')}</article></section>`;
  const modelPanel = renderBaselineFlow(views);
  return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(caseJson.identity?.title || '未命名用例')} - 执行报告</title><style>${styles()}${checkpointAndMermaidStyles()}${flowWorkspaceStyles()}</style></head><body><div class="product-shell"><header class="product-bar"><a class="product-brand" href="../../../../index.html"><span>MV</span><div><b>MAVT</b><small>移动端 AI 视觉测试</small></div></a><div><b>执行报告</b><small>${escapeHtml(report.execution?.batchId || report.execution?.executionId || '-')}</small></div></header><main class="workspace"><div class="report-page" data-platform="${escapeHtml(platform)}"><header class="report-head"><a class="back-button" href="../../../../index.html">${icon('arrowLeft')}返回总览</a><div class="report-title"><span>${escapeHtml(platformLabel)} · 用例 ${escapeHtml(caseJson.identity?.caseNo || '-')}</span><h1>${escapeHtml(caseJson.identity?.title || '未命名用例')}</h1><small>${escapeHtml(report.execution?.executionId || '-')}</small></div><div class="report-result"><span class="status status-${escapeHtml(className(verdict))}"><i></i>${escapeHtml(label(VERDICT_LABELS, verdict, '未知'))}${verdict === 'PASS' && views.coverage.waived ? ` · 含 ${views.coverage.waived} 个豁免` : ''}</span><span><b>${passed}/${views.coverage.total}</b>检查点已处置</span><span><b>${escapeHtml(optionalDuration(display.durationMs))}</b>总耗时</span></div></header><nav class="report-tabs" aria-label="报告内容">${tabs.map(([key, text], index) => `<button type="button" role="tab" class="${index === 0 ? 'active' : ''}" aria-selected="${index === 0}" data-report-tab="${key}" data-panel="${key}-panel">${text}${key === 'logs' ? `<i>${trace.entries.length}</i>` : ''}</button>`).join('')}</nav><div class="report-content">${renderOutcome(report, trace, narrative, views)}${sourcePanel}${modelPanel}${renderProcess(report, trace, narrative, shots)}${trace.plans.length ? renderRuntimePlans(trace) : ''}${renderLogs(report, trace)}</div>${shotViewer()}${mermaidViewer()}</div></main></div>${behavior(shots)}</body></html>\n`;
}

module.exports = { renderCurrentContextHtml };
